:root {
  --bg: #1e1e2f;
  --card: #2a2a40;
  --accent: #6c5ce7;
  --accent-light: #a29bfe;
  --text: #f0f0f5;
  --text-muted: #b0b0c0;
  --bar-bg: #3a3a55;
  --bar-fill: #6c5ce7;
  --bar-fill-voted: #00cec9;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  background: var(--bg);
  color: var(--text);
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  line-height: 1.5;
  display: flex;
  justify-content: center;
  align-items: center;
  min-height: 100vh;
  padding: 16px;
}

.poll-card {
  background: var(--card);
  border-radius: 16px;
  padding: 24px;
  width: 100%;
  max-width: 480px;
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.4);
}

.poll-question {
  font-size: 1.5rem;
  margin-bottom: 24px;
  text-align: center;
  color: var(--accent-light);
}

.options {
  display: flex;
  flex-direction: column;
  gap: 16px;
  margin-bottom: 16px;
}

.option {
  background: var(--bar-bg);
  border-radius: 12px;
  padding: 12px 16px;
  cursor: pointer;
  border: 2px solid transparent;
  transition: border-color 0.2s, background 0.2s;
  position: relative;
  overflow: hidden;
}

.option:hover {
  border-color: var(--accent-light);
}

.option:focus-visible {
  outline: 3px solid var(--accent-light);
  outline-offset: 2px;
}

.option.voted {
  border-color: var(--bar-fill-voted);
}

.option-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 8px;
  font-weight: 600;
  position: relative;
  z-index: 1;
}

.option-label {
  font-size: 1.1rem;
}

.option-stats {
  font-size: 0.9rem;
  color: var(--text-muted);
}

.bar-container {
  height: 8px;
  background: var(--bar-bg);
  border-radius: 4px;
  overflow: hidden;
  position: relative;
  z-index: 1;
}

.bar-fill {
  height: 100%;
  width: 0%;
  background: var(--bar-fill);
  border-radius: 4px;
  transition: width 0.3s ease;
}

.option.voted .bar-fill {
  background: var(--bar-fill-voted);
}

.status {
  text-align: center;
  font-size: 0.9rem;
  color: var(--text-muted);
  min-height: 1.5em;
  margin-bottom: 16px;
}

.reset-btn {
  display: block;
  width: 100%;
  padding: 12px;
  font-size: 1rem;
  font-weight: 600;
  background: var(--accent);
  color: var(--text);
  border: none;
  border-radius: 12px;
  cursor: pointer;
  transition: background 0.2s, transform 0.1s;
}

.reset-btn:hover {
  background: var(--accent-light);
  color: var(--bg);
}

.reset-btn:focus-visible {
  outline: 3px solid var(--accent-light);
  outline-offset: 2px;
}

.reset-btn:active {
  transform: scale(0.98);
}

@media (max-width: 400px) {
  .poll-card {
    padding: 16px;
  }
  .poll-question {
    font-size: 1.25rem;
  }
  .option-header {
    flex-direction: column;
    align-items: flex-start;
    gap: 4px;
  }
}

'use strict';

document.addEventListener('DOMContentLoaded', () => {
  const options = [
    { id: 'red', label: 'Red' },
    { id: 'blue', label: 'Blue' },
    { id: 'green', label: 'Green' },
    { id: 'purple', label: 'Purple' }
  ];

  let votes = {};
  let userVote = null;

  const optionsContainer = document.getElementById('options');
  const statusEl = document.getElementById('status');
  const resetBtn = document.getElementById('reset');

  function initVotes() {
    options.forEach(opt => {
      votes[opt.id] = 0;
    });
    userVote = null;
  }

  function totalVotes() {
    return Object.values(votes).reduce((a, b) => a + b, 0);
  }

  function render() {
    const total = totalVotes();
    optionsContainer.innerHTML = '';

    options.forEach(opt => {
      const count = votes[opt.id];
      const pct = total === 0 ? 0 : Math.round((count / total) * 100);
      const isVoted = userVote === opt.id;

      const div = document.createElement('div');
      div.className = 'option' + (isVoted ? ' voted' : '');
      div.setAttribute('role', 'button');
      div.setAttribute('tabindex', '0');
      div.setAttribute('aria-label', `${opt.label}: ${count} vote${count !== 1 ? 's' : ''}, ${pct}%`);
      div.dataset.optionId = opt.id;

      div.innerHTML = `
        <div class="option-header">
          <span class="option-label">${opt.label}</span>
          <span class="option-stats">${count} vote${count !== 1 ? 's' : ''} · ${pct}%</span>
        </div>
        <div class="bar-container">
          <div class="bar-fill" style="width: ${pct}%"></div>
        </div>
      `;

      div.addEventListener('click', () => handleVote(opt.id));
      div.addEventListener('keydown', (e) => {
        if (e.key === 'Enter' || e.key === ' ') {
          e.preventDefault();
          handleVote(opt.id);
        }
      });

      optionsContainer.appendChild(div);
    });

    if (userVote) {
      statusEl.textContent = `You voted for ${options.find(o => o.id === userVote).label}. Click another option to change your vote.`;
    } else {
      statusEl.textContent = 'Click an option to vote.';
    }
  }

  function handleVote(optionId) {
    if (userVote === optionId) return;

    if (userVote) {
      votes[userVote] = Math.max(0, votes[userVote] - 1);
    }

    userVote = optionId;
    votes[optionId] = (votes[optionId] || 0) + 1;
    render();
  }

  function resetVotes() {
    initVotes();
    render();
  }

  initVotes();
  render();

  resetBtn.addEventListener('click', resetVotes);
});
